#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_append_n_resizes_and_appends_success(void) {
    // Setup: create a buffer with small initial size and some data
    // We'll append more data than fits, so buffer_resize is called and succeeds

    // Create buffer with "foo" (len=3), initial size 4 (just enough for "foo\0")
    buffer_t *buf = buffer_new_with_size(4);
    TEST_ASSERT_NOT_NULL(buf);
    strcpy(buf->data, "foo");

    // Prepare string to append
    const char *to_append = "barbaz";
    size_t append_len = 6; // append all of "barbaz"

    // This will require resizing: needed = 3+6=9, but buf->len=4, so resize is triggered

    int ret = buffer_append_n(buf, to_append, append_len);

    // Assert: function returns 0 (success)
    TEST_ASSERT_EQUAL_INT(0, ret);

    // Buffer should now contain "foobarbaz"
    helper_assert_buffer_data_equals(buf, "foobarbaz");

    // Buffer string length should be 9
    helper_assert_buffer_length(buf, 9);

    // Buffer should be null-terminated
    TEST_ASSERT_EQUAL_CHAR('\0', buf->data[9]);

    // Clean up
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_append_n_resizes_and_appends_success);
    return UNITY_END();
}

